_DEFAULT_LOCK = threading.Lock()
_DEFAULT_CONDUCTOR: Optional[ConductorContext] = None


def get_default_conductor(
    *,
    lib_path: Optional[Union[str, Path]] = None,
    lut_path: Any = _AUTO_LUT,
    require_fast_lut: bool = False,
) -> ConductorContext:
    global _DEFAULT_CONDUCTOR
    with _DEFAULT_LOCK:
        if _DEFAULT_CONDUCTOR is None:
            _DEFAULT_CONDUCTOR = ConductorContext(
                lib_path=lib_path,
                lut_path=lut_path,
                require_fast_lut=require_fast_lut,
            )
        return _DEFAULT_CONDUCTOR


def close_default_conductor() -> None:
    global _DEFAULT_CONDUCTOR
    with _DEFAULT_LOCK:
        inst = _DEFAULT_CONDUCTOR
        _DEFAULT_CONDUCTOR = None
    if inst is not None:
        inst.close()


atexit.register(close_default_conductor)


